package com.exampro.service;
import com.exampro.dto.ApiDtos.*;import com.exampro.entity.*;import com.exampro.exception.*;import com.exampro.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @Transactional public class ExamService {private final ExamRepository exams;private final QuestionRepository questions;public ExamService(ExamRepository e,QuestionRepository q){exams=e;questions=q;}public List<ExamResponse> all(){return exams.findAll().stream().map(this::dto).toList();}public ExamResponse get(Long id){return dto(exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found")));}
 public ExamResponse create(ExamRequest r){if(r.availableFrom()!=null&&r.availableUntil()!=null&&!r.availableUntil().isAfter(r.availableFrom()))throw new BadRequestException("availableUntil must be after availableFrom");Exam e=new Exam();e.setTitle(r.title());e.setDescription(r.description());e.setDurationMinutes(r.durationMinutes());e.setPassingPercentage(r.passingPercentage());e.setAvailableFrom(r.availableFrom());e.setAvailableUntil(r.availableUntil());return dto(exams.save(e));}
 public ExamResponse update(Long id,ExamRequest r){Exam e=exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found"));e.setTitle(r.title());e.setDescription(r.description());e.setDurationMinutes(r.durationMinutes());e.setPassingPercentage(r.passingPercentage());e.setAvailableFrom(r.availableFrom());e.setAvailableUntil(r.availableUntil());return dto(exams.save(e));}
 @Transactional public ExamResponse assign(Long id,AssignQuestionsRequest r){Exam e=exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found"));Set<Long> ids=new HashSet<>(r.questionIds());if(ids.size()!=r.questionIds().size())throw new BadRequestException("Duplicate question IDs are not allowed");List<Question> found=questions.findAllById(ids);if(found.size()!=ids.size())throw new NotFoundException("One or more questions not found");e.getQuestions().addAll(found);return dto(exams.save(e));}
 public void delete(Long id){Exam e=exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found"));if(!e.getQuestions().isEmpty())e.getQuestions().clear();exams.delete(e);}
 @Transactional public ExamResponse unassign(Long id,Long questionId){Exam e=exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found"));Question q=questions.findById(questionId).orElseThrow(()->new NotFoundException("Question not found"));e.getQuestions().remove(q);return dto(exams.save(e));}
 public List<QuestionResponse> examQuestions(Long id){Exam e=exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found"));return e.getQuestions().stream().map(q->new QuestionResponse(q.getId(),q.getText(),q.getDifficulty().name(),q.getMarks(),q.getSubject().getId(),q.getSubject().getName(),q.getOptions().stream().map(o->new OptionResponse(o.getId(),o.getText())).toList())).toList();}
 public List<AdminQuestionResponse> adminExamQuestions(Long id){Exam e=exams.findById(id).orElseThrow(()->new NotFoundException("Exam not found"));return e.getQuestions().stream().map(q->new AdminQuestionResponse(q.getId(),q.getText(),q.getDifficulty().name(),q.getMarks(),q.getSubject().getId(),q.getSubject().getName(),q.getOptions().stream().map(o->new AdminOptionResponse(o.getId(),o.getText(),o.isCorrect())).toList())).toList();}
 private ExamResponse dto(Exam e){return new ExamResponse(e.getId(),e.getTitle(),e.getDescription(),e.getDurationMinutes(),e.getPassingPercentage(),e.getMaximumMarks(),e.getAvailableFrom(),e.getAvailableUntil(),e.getQuestions().stream().map(Question::getId).toList(),e.isAvailableNow());}}
